def call_sites(text: str) -> int:
    """LIVE CALL SITES, not text mentions: an AST Attribute or Name node whose
    identifier is the banned simplifier.  Prose, docstrings and gate names that
    merely NAME it are not call sites and are counted separately."""
    try:
        tree = ast.parse(text)
    except SyntaxError:
        return -1
    return sum(1 for node in ast.walk(tree)
               if (isinstance(node, ast.Attribute) and node.attr == _NS)
               or (isinstance(node, ast.Name) and node.id == _NS))


def hygiene_report() -> dict:
    """The four repaired sites ABSENT; the residue COUNTED and never hidden.

    TEXT MENTIONS AND LIVE CALL SITES ARE COUNTED SEPARATELY, because most
    surviving occurrences in this lane are prose about the repair rather than
    arithmetic: the pair (mentions, call sites) is the honest report.
    """
    absent = []
    for path, needle in REPAIRED_SITES:
        try:
            text = (ROOT / path).read_text(encoding="utf-8")
        except OSError:
            text = ""
        absent.append(needle not in text and bool(text))
    residue = {}
    for path in HYGIENE_FILES:
        try:
            text = (ROOT / path).read_text(encoding="utf-8")
            residue[path] = (text.count(_NS), call_sites(text))
        except OSError:
            residue[path] = (-1, -1)
    chain_residue = {}
    for name, module in (("b173", b173), ("b172", b172), ("b171", b171),
                         ("b170", b170), ("b166", b166), ("b165", b165)):
        source = getattr(module, "__file__", None) if module is not None else None
        if source:
            text = Path(source).read_text(encoding="utf-8")
            chain_residue[name] = (text.count(_NS), call_sites(text))
        else:
            chain_residue[name] = (-1, -1)
    stale_carries = all(
        _NS in commit_text(STALE_PARENT_COMMIT, path) for path in HYGIENE_FILES)
    return {
        "sites": len(REPAIRED_SITES),
        "absent": all(absent),
        "per_site": tuple(absent),
        "residue_in_repaired_files": residue,
        "residue_in_import_chain": chain_residue,
        "call_sites_in_repaired_files": sum(v[1] for v in residue.values()),
        "call_sites_in_audit_surface": sum(
            chain_residue[name][1] for name in ("b173", "b172", "b171")),
        "call_sites_below_audit_surface": sum(
            chain_residue[name][1] for name in ("b170", "b166", "b165")),
        "stale_tip_carries_sites": stale_carries,
    }


