def bracket(q, den=10 ** 8):
    """The checker's own bracket form: [floor(|q| den)/den, ceil(|q| den)/den]."""
    value = sp.Abs(sp.cancel(q))
    return (R(sp.floor(value * den), den), R(sp.ceiling(value * den), den))


def floor_scaled(q, den=10 ** 7):
    """floor(|q| * den) as an exact Integer."""
    return sp.floor(sp.Abs(sp.cancel(q)) * den)


