def dm_det(matrix: sp.Matrix):
    """Exact determinant by DomainMatrix fraction-field elimination."""
    dm = DomainMatrix.from_Matrix(matrix)
    return sp.expand(dm.domain.to_sympy(dm.det()))


def norm2(value):
    """|z|^2 for an exact Gaussian rational, as an exact positive rational."""
    out = sp.cancel(sp.re(value) ** 2 + sp.im(value) ** 2)
    return out


def ldl_certificate(matrix: sp.Matrix) -> dict:
    """Exact unpivoted Hermitian LDL*: positive pivots iff PD.  The pivot product
    is gated against the DomainMatrix determinant when the recurrence completes."""
    n = matrix.rows
    lower = sp.eye(n)
    pivots: list = []
    for j in range(n):
        pivot = sp.cancel(matrix[j, j] - sum(
            lower[j, k] * sp.conjugate(lower[j, k]) * pivots[k]
            for k in range(j)))
        pivot = sp.expand_complex(pivot)
        if sp.im(pivot) != 0:
            return {"pd": False, "first_bad": j, "pivot": None,
                    "positive": len(pivots), "det": None, "hermitian": False}
        pivot = sp.cancel(sp.re(pivot))
        if pivot <= 0:
            return {"pd": False, "first_bad": j, "pivot": pivot,
                    "positive": sum(1 for v in pivots if v > 0), "det": None,
                    "hermitian": True}
        pivots.append(pivot)
        for i in range(j + 1, n):
            numerator = matrix[i, j] - sum(
                lower[i, k] * sp.conjugate(lower[j, k]) * pivots[k]
                for k in range(j))
            lower[i, j] = sp.cancel(numerator / pivot)
    determinant = sp.cancel(sp.prod(pivots))
    return {"pd": True, "first_bad": None, "pivot": None, "positive": n,
            "det": determinant, "hermitian": True,
            "gated": determinant == dm_det(matrix)}


class Fixture:
    """Q-only exact prefix of the block-174 gate solve's Width class.

    Same landed Bench, same carrier-field shape, same carrier substitution, same
    committed constants and the same records wiring, ending at
    sp.expand(bench.Q.subs(sub)).  An imposed t-uniform volume PATTERN replaces
    the landed volume law when one is supplied; with pattern None the landed
    xgraded law is called verbatim.  Gate B anchors this class against Width.
    """

    def __init__(self, lx: int, pattern=None, tag: str = "f",
                 cover_t: int = COVER_T):
        self.lx = lx
        self.cover_t = cover_t
        self.pattern = (None if pattern is None
                        else tuple(sp.sympify(v) for v in pattern))
        self.bench = b170.Bench(f"b174-{tag}-{cover_t}x{lx}", cover_t, lx)
        self.fx = self.bench.fx
        self.c = self.bench.c
        self.T = self.bench.T
        self.N = self.bench.N
        self.free_levels = tuple(
            t for t in range(self.T) if t not in {(self.c - 1) % self.T, self.c})
        self.tstar = self.free_levels[-1]
        self._site = None

    def volume(self, t: int, x: int):
        if self.pattern is None:
            return b171.volume("xgraded", t, x)
        return self.pattern[x % self.lx]

    def field(self, sigma, records: dict) -> dict:
        pinned = {(self.c - 1) % self.T, self.c}
        return {
            (t, x): (Z0 if t in pinned
                     else sp.sympify(records.get((t, x), sigma)),
                     self.volume(t, x))
            for (t, x) in self.fx.CELLS
        }

    def substitution(self, sigma, records, sx, st, mass) -> dict:
        out = b166.carrier_substitution(self.fx, self.field(sigma, records))
        out[b171.SX] = sp.sympify(sx)
        out[b171.ST] = sp.sympify(st)
        out[b171.MASS] = sp.sympify(mass)
        return out

    def site(self):
        if self._site is None:
            self._site = b171.Site(f"b174-site-12x{self.lx}", COVER_T, self.lx)
        return self._site

    def q(self, records: dict = None, sigma=b171.CARRIER_SIGMA,
          sx=b171.BENCH_SX, st=Z0, mass=b171.BENCH_MASS, action="bench",
          gre=R(1, 3), gim=R(1, 4)) -> sp.Matrix:
        sub = self.substitution(sigma, records or {}, sx, st, mass)
        symbolic = (self.bench.Q if action == "bench"
                    else {"holo_t": self.site().Q_holo_t,
                          "holo_x": self.site().Q_holo_x}[action])
        out = sp.expand(symbolic.subs(sub))
        if action != "bench":
            out = sp.expand(out.subs({b171.GRE: sp.sympify(gre),
                                      b171.GIM: sp.sympify(gim)}))
        return out


def constant_pattern(lx: int) -> tuple:
    return (ONE,) * lx


def twin_pattern(lx: int) -> tuple:
    """Two half-turn-related halves with one central remote mismatch, padded by
    9/5, preserving the oriented twin blanket (7/5, 6/5, 8/5) at both twins."""
    half = lx // 2
    left = [PAD_VOLUME] * half
    left[0] = R(6, 5)
    left[1] = R(8, 5)
    left[-1] = R(7, 5)
    left[half // 2] = REMOTE_LEFT
    right = list(left)
    right[half // 2] = REMOTE_RIGHT
    return tuple(left + right)


def control_pattern(pattern: tuple) -> tuple:
    out = list(pattern)
    out[1] = out[1] + CONTROL_DELTA
    return tuple(out)


def circle_distance(lx: int, x: int, y: int) -> int:
    return min((x - y) % lx, (y - x) % lx)


def pattern_certificate(pattern: tuple) -> dict:
    lx = len(pattern)
    half = lx // 2
    remote = half // 2
    def blanket(x):
        return (pattern[(x - 1) % lx], pattern[x], pattern[(x + 1) % lx])
    return {
        "twins": (0, half),
        "blanket": blanket(0),
        "same_blanket": blanket(0) == blanket(half),
        "twin_distance": circle_distance(lx, 0, half),
        "mismatches": tuple(x for x in range(half)
                            if pattern[x] != pattern[x + half]),
        "remote_distances": (circle_distance(lx, remote, 0),
                             circle_distance(lx, remote, half)),
        "translations": tuple(
            k for k in range(1, lx)
            if all(pattern[x] == pattern[(x + k) % lx] for x in range(lx))),
        "reflections": tuple(
            q for q in range(lx)
            if all(pattern[x] == pattern[(q - x) % lx] for x in range(lx))),
    }


def menu_states(fixture: Fixture, level: int, x: int, **cfg) -> tuple:
    """One (det, |det|^2, LDL certificate) triple per menu value at one cell."""
    out = []
    for value in MENU:
        q = fixture.q({(level, x): value}, **cfg)
        det = dm_det(q)
        out.append({"det": det, "n2": norm2(det),
                    "cert": ldl_certificate(sp.expand((q + q.H) / 2))})
    return tuple(out)


def normalize(raw: tuple) -> tuple:
    total = sp.cancel(sum(raw))
    return tuple(sp.cancel(v / total) for v in raw)


def readout_laws(states: tuple) -> dict:
    """THE FOUR READOUT MAPS, each normalized over the menu.

    sq   = |det Q|^-2         exact rational, positive
    herm = det(herm Q)^-1     exact rational, positive exactly where herm(Q) > 0
    mod  = |det Q|^-1         exact ALGEBRAIC, generally irrational: represented
                              by its norm vector and compared by the exact ratio
                              criterion rather than by radical arithmetic
    re   = Re(det Q^-1)       exact rational, not positive in general
    """
    laws = {}
    raw_sq = tuple(sp.cancel(ONE / s["n2"]) for s in states)
    laws["sq"] = {"raw": raw_sq, "law": normalize(raw_sq),
                  "positive": all(v > 0 for v in raw_sq), "rational": True}
    if all(s["cert"]["pd"] for s in states):
        raw_h = tuple(sp.cancel(ONE / s["cert"]["det"]) for s in states)
        laws["herm"] = {"raw": raw_h, "law": normalize(raw_h),
                        "positive": all(v > 0 for v in raw_h), "rational": True}
    else:
        laws["herm"] = {"raw": None, "law": None, "positive": False,
                        "rational": True}
    raw_re = tuple(sp.cancel(sp.re(ONE / s["det"])) for s in states)
    laws["re"] = {"raw": raw_re, "law": normalize(raw_re),
                  "positive": all(v > 0 for v in raw_re), "rational": True}
    laws["mod"] = {"raw": None, "law": None, "positive": True,
                   "rational": False,
                   "norms": tuple(s["n2"] for s in states)}
    return laws


def laws_equal(left: dict, right: dict, key: str) -> bool:
    """Exact equality of two normalized laws under one readout.

    For the three exact-rational readouts this is entry-for-entry equality.  For
    the unsquared modulus it is the exact RATIO criterion: two 1/sqrt(n) laws are
    equal iff every ratio n_b/n_a is the same rational, which decides the
    equality without ever forming a radical.
    """
    if key == "mod":
        ratios = {sp.cancel(b / a)
                  for a, b in zip(left["mod"]["norms"], right["mod"]["norms"])}
        return len(ratios) == 1
    if left[key]["law"] is None or right[key]["law"] is None:
        return False
    return left[key]["law"] == right[key]["law"]


def law_gap(left: dict, right: dict, key: str):
    """max_a |P_left(a) - P_right(a)| for an exact-rational readout."""
    delta = tuple(sp.cancel(a - b)
                  for a, b in zip(left[key]["law"], right[key]["law"]))
    return max(sp.Abs(v) for v in delta), delta


def profile_of(fixture: Fixture, records: dict) -> tuple:
    """The landed W9 record-slice class profile at t*, on this fixture's Q."""
    q = fixture.q(records)
    qi = exact_inv(q)
    w9 = sp.expand((qi + qi.H) / 2)
    rows = [fixture.lx * (fixture.tstar % fixture.T) + x
            for x in range(fixture.lx)]
    diagonal = [sp.expand(w9[k, k]) for k in rows]
    total = sp.expand(sum(diagonal))
    return tuple(sp.cancel(v / total) for v in diagonal), q, qi


def transformed(q: sp.Matrix, lx: int, map_x) -> sp.Matrix:
    return sp.Matrix(q.rows, q.cols, lambda i, j: q[
        lx * (i // lx) + map_x(i % lx), lx * (j // lx) + map_x(j % lx)])


def diff_report(left: sp.Matrix, right: sp.Matrix) -> tuple:
    found = []
    for i in range(left.rows):
        for j in range(left.cols):
            value = sp.expand(left[i, j] - right[i, j])
            if value != 0:
                found.append((i, j, value))
    return len(found), (found[0] if found else None)


