cong_inertia = b170.cong_inertia
b165_inertia = b165.real_symmetric_inertia


def measure_convention() -> dict:
    """THE COLLISION, MEASURED on identical matrices and never asserted.

    The instrument is the LANDED one -- b170.convention_probe -- which calls the
    b163/b164 helper congruence_inertia and the Block 165 helper
    real_symmetric_inertia on the same three probe matrices and additionally
    cross-checks its own congruence instrument on a 28-member exact battery.
    This block does not rebuild the instrument; it reads it.
    """
    probe = b170.convention_probe()
    return {
        "pairs": probe["pairs"],
        "landed_psd": probe["landed_psd"],
        "here_psd": probe["here_psd"],
        "orders_differ": probe["orders_differ"],
        "instrument_agree": probe["instrument_agree"],
    }


def measure_support_invariance() -> dict:
    """THE SUPPORT-INVARIANCE ARGUMENT, as a measured structure.

    Two strictly positive odds vectors on the SAME four-element menu with the
    SAME support.  The realizable record-configuration set over a sampled site
    set is identical; the frequency-matching target is not.  The three
    qualifications the cross-model review attached are carried as flags:
    the odds ARE law content, the invariance is at CONFIGURATION level, and the
    all-same-pick example is conditional on the pick staying in support.
    """
    odds_a = (R(1, 4), R(1, 4), R(1, 4), R(1, 4))
    odds_b = (R(2, 5), R(1, 5), R(1, 5), R(1, 5))
    support_a = tuple(i for i, v in enumerate(odds_a) if v > 0)
    support_b = tuple(i for i, v in enumerate(odds_b) if v > 0)
    sites = 2
    configurations = [
        (i, j) for i in range(len(MENU)) for j in range(len(MENU))]
    allowed_a = [c for c in configurations
                 if all(k in support_a for k in c)]
    allowed_b = [c for c in configurations
                 if all(k in support_b for k in c)]
    constant = (0,) * sites
    return {
        "menu": MENU,
        "odds_a": odds_a,
        "odds_b": odds_b,
        "supports_equal": support_a == support_b,
        "supports_full": len(support_a) == len(MENU),
        "odds_differ": odds_a != odds_b,
        "sums_are_one": (sum(odds_a) == 1 and sum(odds_b) == 1),
        "configurations": len(configurations),
        "configuration_sets_equal": allowed_a == allowed_b == configurations,
        "constant_configuration_allowed": (constant in allowed_a
                                           and constant in allowed_b),
        "frequency_targets_differ": odds_a != odds_b,
        # THE THREE QUALIFICATIONS, and all three are the reviewer's.
        "odds_are_law_content": True,
        "configuration_level_only": True,
        "all_same_pick_conditional": True,
        # The refuted freeness route is NOT used and is recorded as refuted.
        "freeness_route_used": False,
    }


def measure_bench(deep: bool) -> dict:
    """The bench anchor: this block's Q builder against the landed Width, the
    determinant route against Berkowitz, and the LDL* pivot product against the
    DomainMatrix determinant."""
    fixture = Fixture(4, tag="bench")
    records = {(RECORD_LEVEL, 0): Z0}
    q = fixture.q(records)
    qi = exact_inv(q)
    s = herm(q)
    w9 = sp.expand((qi + qi.H) / 2)
    eye = sp.eye(fixture.N)
    det_dm = dm_det(q)
    det_bk = sp.expand(q.det(method="berkowitz"))
    cert = ldl_certificate(s)
    landed_field = b171.field(fixture.fx, fixture.c, b171.CARRIER_SIGMA,
                              "xgraded", records)
    return {
        "T_phys": fixture.T,
        "N": fixture.N,
        "tstar": fixture.tstar,
        "free_levels": fixture.free_levels,
        "q_symbol_free": not q.free_symbols,
        "field_matches_landed": fixture.field(b171.CARRIER_SIGMA, records)
        == landed_field,
        "inverse_residual_zero": (is_zero(sp.expand(q * qi) - eye)
                                  and is_zero(sp.expand(qi * q) - eye)),
        "congruence_zero": is_zero(w9 - sp.expand(qi * s * qi.H)),
        "hermq_inertia": tuple(b165_inertia(s)),
        "det_routes_agree": sp.expand(det_dm - det_bk) == 0,
        "det_nonzero": det_dm != 0,
        "ldl_pd": cert["pd"],
        "ldl_pivots_positive": cert["positive"],
        "ldl_gated": bool(cert.get("gated")),
        "menu_is_sigma_classes": MENU == tuple(b171.SIGMA_CLASSES),
    }


