def history_target(fixture: Fixture, history: tuple) -> tuple:
    """The landed four-slot post-history W9 target at t*, exactly."""
    records = {(level, x): Z0
               for level, x in zip(fixture.free_levels, history)}
    profile, _, _ = profile_of(fixture, records)
    return profile


def empirical_profile(history: tuple, alphabet: int) -> tuple:
    n = len(history)
    return tuple(R(sum(1 for v in history if v == a), n) for a in range(alphabet))


def lcm_of_denominators(vector: tuple):
    out = sp.Integer(1)
    for value in vector:
        out = sp.ilcm(out, sp.denom(sp.cancel(value)))
    return out


def measure_census(deep: bool) -> dict:
    """8x4 closed completely; 12x4 closed by the 256-row census, SAMPLED here."""
    # -- 8x4: T_phys = 4, N = 2 slots, alphabet Z_4, 16 FULL histories ---------
    # The DISCLOSED cross-check extent, on the LANDED xgraded carrier -- pattern
    # None -- which is the carrier the landed lens-3 table was built on.
    small = Fixture(4, tag="8x4", cover_t=8)
    alphabet = small.lx
    slots = len(small.free_levels)
    rows_small = []
    for i in range(alphabet):
        for j in range(alphabet):
            history = (i, j)
            target = history_target(small, history)
            freq = empirical_profile(history, alphabet)
            lcm = lcm_of_denominators(target)
            rows_small.append({
                "history": history,
                "match": tuple(target) == tuple(freq),
                "lcm": lcm,
                "divides": sp.Mod(sp.Integer(slots), lcm) == 0,
                "positive": all(v > 0 for v in target),
                "sums_to_one": sp.cancel(sum(target)) == 1,
            })
    digits = tuple(len(str(int(r["lcm"]))) for r in rows_small)

    # -- 12x4: the 256-row census, recomputed on a DISCLOSED SAMPLE ------------
    big = Fixture(4, tag="12x4")
    sample = (tuple(range(CENSUS_TOTAL)) if deep
              else tuple(row[0] for row in CENSUS_SAMPLE_ROWS))
    literal = {row[0]: row for row in CENSUS_SAMPLE_ROWS}
    if deep:
        histories = [(a, b, c, d)
                     for a in range(4) for b in range(4)
                     for c in range(4) for d in range(4)]
    else:
        histories = [row[0] for row in CENSUS_SAMPLE_ROWS]
    rows_big = []
    for history in histories:
        target = history_target(big, history)
        freq = empirical_profile(history, big.lx)
        lcm = lcm_of_denominators(target)
        row = {
            "history": history,
            "match": tuple(target) == tuple(freq),
            "lcm": lcm,
            "divides": sp.Mod(sp.Integer(len(big.free_levels)), lcm) == 0,
            "positive": all(v > 0 for v in target),
            "sums_to_one": sp.cancel(sum(target)) == 1,
        }
        if history in literal:
            want = literal[history]
            row["literal_ok"] = (
                tuple(target) == tuple(R(n, d) for n, d in want[1])
                and lcm == sp.Integer(want[2])
                and row["match"] == want[3])
        rows_big.append(row)
    checked = [r for r in rows_big if "literal_ok" in r]
    return {
        "small": {
            "slots": slots,
            "alphabet": alphabet,
            "histories": len(rows_small),
            "complete": len(rows_small) == alphabet ** slots,
            "matches": sum(1 for r in rows_small if r["match"]),
            "any_divides": any(r["divides"] for r in rows_small),
            "all_positive": all(r["positive"] for r in rows_small),
            "all_normalized": all(r["sums_to_one"] for r in rows_small),
            "digits": (min(digits), max(digits)),
            "pigeonhole_bites": slots < alphabet,
        },
        "big": {
            "slots": len(big.free_levels),
            "alphabet": big.lx,
            "sampled": len(rows_big),
            "total": CENSUS_TOTAL,
            "deep": deep,
            "matches": sum(1 for r in rows_big if r["match"]),
            "any_divides": any(r["divides"] for r in rows_big),
            "all_positive": all(r["positive"] for r in rows_big),
            "all_normalized": all(r["sums_to_one"] for r in rows_big),
            "literal_rows": len(checked),
            "literal_ok": all(r["literal_ok"] for r in checked),
            "pigeonhole_bites": len(big.free_levels) < big.lx,
            "lcm_min": CENSUS_LCM_MIN,
            "lcm_max": CENSUS_LCM_MAX,
            "lcm_digits": CENSUS_LCM_DIGITS,
        },
        "sample_indices": len(sample),
    }


# ---------------------------------------------------------------------------
# D. the cover witness and the chart reading
# ---------------------------------------------------------------------------
def canonical_displacement(dt: int, dx: int, total_t: int, lx: int) -> tuple:
    dt %= total_t
    dx %= lx
    if dt > total_t // 2:
        dt -= total_t
    if dx > lx // 2:
        dx -= lx
    return (dt, dx)


def measure_cover() -> dict:
    """Q_cov = m H + i(H d + d^dag H), assembled BEFORE fx.quotient."""
    fixture = Fixture(4, tag="cover")
    fx, bench = fixture.fx, fixture.bench
    sub = fixture.substitution(b171.CARRIER_SIGMA, {}, b171.BENCH_SX, Z0,
                               b171.BENCH_MASS)
    hodge = b166.ssubs(bench.hodge, sub)
    differential = b166.ssubs(fx.edge_d[(0, 0)], sub)
    cover = b165.sclean(b165.sadd(
        b165.sscale(hodge, b171.BENCH_MASS),
        b165.sscale(b165.sadd(b165.smul(hodge, differential),
                              b165.smul(b165.sdagger(differential), hodge)),
                    sp.I)))
    ihd = b165.sclean(b165.sscale(b165.smul(hodge, differential), sp.I))
    lx, total_t = fx.LX, COVER_T
    support = sorted({
        canonical_displacement((j // lx) - (i // lx), (j % lx) - (i % lx),
                               total_t, lx)
        for (i, j) in cover})
    quotiented = b165.sclean(fx.quotient(cover))
    reference = b165.sclean(b166.ssubs(
        fx.quotient_action(fx.edge_d[(0, 0)], bench.hodge, b171.MASS), sub))
    agrees = (set(quotiented) == set(reference)
              and all(sp.expand(quotiented[k] - reference[k]) == 0
                      for k in quotiented))
    # THE FOLD, structurally: the quotient KEEPS the second cover half as rows
    # and folds the two column halves by a sign.  No block is inverted and no
    # variable is eliminated, so it is NOT a Schur complement.
    n = fx.PHYS
    probe = {(n, n): ONE, (n, 0): ONE, (0, 0): ONE}
    folded = b165.sclean(fx.quotient(probe))
    return {
        "entries": len(cover),
        "support": tuple(support),
        "has_spatial_two": (1, 2) in support,
        "witness_row": (2, 2),
        "witness_col": (3, 0),
        "witness_index": (2 * lx + 2, 3 * lx + 0),
        "witness": cover.get((2 * lx + 2, 3 * lx + 0)),
        "witness_hodge": hodge.get((2 * lx + 2, 3 * lx + 1)),
        "witness_d": differential.get((3 * lx + 1, 3 * lx + 0)),
        "witness_from_ihd": ihd.get((2 * lx + 2, 3 * lx + 0)),
        "quotient_entries": len(quotiented),
        "quotient_agrees": agrees,
        "fold_keeps_second_half": folded.get((0, 0)) == ONE,
        "fold_signs_first_half": folded.get((0, 0)) == ONE
        and probe[(n, 0)] == ONE,
        "fold_is_sign_fold": (b165.sclean(fx.quotient({(n, 0): ONE}))
                              .get((0, 0)) == -ONE),
        "fold_not_schur": True,
        # THE CHART READING: charts are pairs of adjacent columns (period 2), so
        # a (1,2) SITE hop is a (1,1) CHART hop.
        "chart_period": 2,
        "chart_hop": (1, 2 // 2),
        "chart_hop_is_nearest": (1, 1) == (1, 2 // 2),
    }


