# ---------------------------------------------------------------------------
DIAL_POINTS = (
    ("s_t = 0", {"st": Z0}),
    ("s_t = 1/8", {"st": R(1, 8)}),
    ("s_t = 1/4", {"st": R(1, 4)}),
    ("holo_t 0 + 0i", {"action": "holo_t", "gre": Z0, "gim": Z0}),
    ("holo_t 0 + i/4", {"action": "holo_t", "gre": Z0, "gim": R(1, 4)}),
    ("holo_t 1/3 + i/4", {"action": "holo_t", "gre": R(1, 3), "gim": R(1, 4)}),
    ("holo_x 0 + 0i", {"action": "holo_x", "gre": Z0, "gim": Z0}),
    ("holo_x 0 + i/4", {"action": "holo_x", "gre": Z0, "gim": R(1, 4)}),
    ("holo_x 1/3 + i/4", {"action": "holo_x", "gre": R(1, 3), "gim": R(1, 4)}),
    ("sigma = 0", {"sigma": Z0}),
    ("sigma = 3/5", {"sigma": R(3, 5)}),
    ("sigma = 4/5", {"sigma": R(4, 5)}),
    ("m = 0", {"mass": Z0}),
    ("m = 1", {"mass": ONE}),
    ("m = 3", {"mass": sp.Integer(3)}),
)
# THE DISCLOSED BASELINE SAMPLE: five nonzero-mass points spanning four of the
# five transport families, plus the m = 0 boundary point, which is never sampled
# away because it carries the domain correction.
BASELINE_DIALS = (0, 2, 5, 11, 12, 13)
ZERO_MASS_INDEX = 12


def measure_family() -> dict:
    """THE LAW FAMILY at the constant carrier and at the L_x = 8 twin fixture."""
    const = Fixture(4, pattern=constant_pattern(4), tag="const")
    cells = {}
    for column in (0, 1, 2):
        cells[f"const{column}"] = readout_laws(
            menu_states(const, RECORD_LEVEL, column))
    pattern = twin_pattern(8)
    twin = Fixture(8, pattern=pattern, tag="twin")
    control = Fixture(8, pattern=control_pattern(pattern), tag="ctrl")
    cells["twin0"] = readout_laws(menu_states(twin, RECORD_LEVEL, 0))
    cells["twin4"] = readout_laws(menu_states(twin, RECORD_LEVEL, 4))
    cells["control0"] = readout_laws(menu_states(control, RECORD_LEVEL, 0))

    obligations = {}
    for key in READOUTS:
        obligations[key] = {
            # 1. covariance under the chart translation group.
            "covariance": laws_equal(cells["const0"], cells["const2"], key),
            # 2. normalization and support.
            "positive": all(cells[name][key]["positive"] for name in cells),
            # 3. dependence ONLY on the nearest-neighbor blanket.
            "blanket_only": laws_equal(cells["twin0"], cells["twin4"], key),
            # 4. nonconstant variation with the blanket.
            "varies": not laws_equal(cells["control0"], cells["twin0"], key),
            # the AUXILIARY parity fingerprint, and it is not an obligation.
            "chart_sensitive": not laws_equal(cells["const0"], cells["const1"],
                                              key),
        }
    profile = {key: (obligations[key]["covariance"], obligations[key]["positive"],
                     obligations[key]["blanket_only"], obligations[key]["varies"])
               for key in READOUTS}
    patterns = {profile[key] for key in READOUTS}

    # THE TWO ALGEBRAIC PROPERTIES OF THE READOUT MAPS, and both are properties
    # OF THE MAP rather than of these numbers, each carried by an exact witness
    # on the map itself.  RATIONALITY fails for the unsquared modulus because
    # |z| = sqrt(2) at z = 1 + i.  POSITIVITY fails for the positive-Re readout
    # because Re(1/z) is negative at z = -1 and zero at z = i.  The fixture-level
    # readings are measured too and DISCLOSED, because at THIS fixture the
    # unsquared modulus happens to come out rational.
    mod_witness = sp.sqrt(norm2(ONE + sp.I))
    mod_map_rational = mod_witness.is_rational is True
    norms = cells["const0"]["mod"]["norms"]
    mod_rational_here = all(sp.sqrt(v).is_rational is True for v in norms)
    re_witness_negative = sp.re(ONE / sp.Integer(-1)) < 0
    re_witness_zero = sp.re(ONE / sp.I) == 0
    map_positive = {"sq": True, "herm": True, "mod": True,
                    "re": not (re_witness_negative or re_witness_zero)}
    exact_rational = {"sq": True, "herm": True, "re": True,
                      "mod": mod_map_rational}
    sensitive = {key for key in READOUTS if obligations[key]["chart_sensitive"]}
    unique = {key for key in sensitive
              if exact_rational[key] and map_positive[key]}
    gap01, _ = law_gap(cells["const0"], cells["const1"], "sq")
    return {
        "cells": cells,
        "fixtures": {"const": const, "twin": twin, "control": control},
        "obligations": obligations,
        "profile": profile,
        "identical_pass_fail": len(patterns) == 1,
        "profiles_pairwise_distinct": len({
            tuple(cells["const0"][key]["law"]) for key in ("sq", "herm", "re")
        }) == 3,
        "surrogate_chart_blind": not obligations["herm"]["chart_sensitive"],
        "squared_chart_sensitive": obligations["sq"]["chart_sensitive"],
        "exact_rational": exact_rational,
        "map_positive": map_positive,
        "mod_map_not_rational": not mod_map_rational,
        "mod_rational_at_this_fixture": mod_rational_here,
        "mod_witness": mod_witness,
        "re_map_not_positive": not map_positive["re"],
        "chart_sensitive_set": tuple(sorted(sensitive)),
        "unique_exact_rational_sensitive": unique == {"sq"},
        "chart_gap": gap01,
        "chart_gap_bracket": bracket(gap01),
        "readouts": len(READOUTS),
    }


def measure_obligations(family: dict, deep: bool) -> dict:
    """The four obligations, measured exactly, with the checker's brackets."""
    cells = family["cells"]
    twin_gap, _ = law_gap(cells["twin0"], cells["twin4"], "sq")
    response, _ = law_gap(cells["control0"], cells["twin0"], "sq")
    herm_gap, _ = law_gap(cells["twin0"], cells["twin4"], "herm")
    herm_response, _ = law_gap(cells["control0"], cells["twin0"], "herm")
    ratio = sp.cancel(response / twin_gap)

    # COVARIANCE IS NOT SYMMETRY-PROTECTED: measured directly on Q.  The twin
    # fixture is REUSED from the family measurement rather than rebuilt.
    twin = family["fixtures"]["twin"]
    q0 = twin.q({})
    translated = transformed(q0, 8, lambda x: (x + 4) % 8)
    t_count, t_witness = diff_report(q0, translated)
    reflections = []
    for axis in range(8):
        moved = transformed(q0, 8, lambda x, q=axis: (q - x) % 8)
        reflections.append(diff_report(q0, moved))

    # THE REALIFICATION CONTROL on the squared readout.
    const = family["fixtures"]["const"]
    qspot = const.q({(RECORD_LEVEL, 0): MENU[2]})
    detspot = dm_det(qspot)
    are, aim = qspot.applyfunc(sp.re), qspot.applyfunc(sp.im)
    realified = are.row_join(-aim).col_join(aim.row_join(are))

    # THE DOMAIN: the 15-point dial census, SAMPLED at baseline.
    dial = Fixture(4, tag="dial")
    indices = tuple(range(len(DIAL_POINTS))) if deep else BASELINE_DIALS
    points = []
    for index in indices:
        label, cfg = DIAL_POINTS[index]
        certs, dets, herms = [], [], []
        for value in MENU:
            q = dial.q({(RECORD_LEVEL, 0): value}, **cfg)
            hermitian = sp.expand((q + q.H) / 2)
            herms.append(is_zero(hermitian))
            dets.append(dm_det(q))
            certs.append(ldl_certificate(hermitian))
        raw = tuple(sp.cancel(ONE / norm2(d)) for d in dets)
        total = sp.cancel(sum(raw))
        points.append({
            "index": index,
            "label": label,
            "zero_mass": index == ZERO_MASS_INDEX,
            "pd_arms": sum(1 for c in certs if c["pd"]),
            "pivots": tuple(c["positive"] for c in certs),
            "dets_nonzero": all(d != 0 for d in dets),
            "weights_positive": all(v > 0 for v in raw)
            and all(sp.cancel(v / total) > 0 for v in raw),
            "first_bad": tuple(c["first_bad"] for c in certs),
            "herm_is_zero": all(herms),
        })
    nonzero = [p for p in points if not p["zero_mass"]]
    zero = [p for p in points if p["zero_mass"]]
    return {
        "twin_gap": twin_gap,
        "twin_bracket": bracket(twin_gap),
        "response": response,
        "response_bracket": bracket(response),
        "ratio": ratio,
        "ratio_in_45_46": bool(sp.Integer(45) < ratio) and bool(ratio < 46),
        "blanket_only_fails": twin_gap != 0,
        "varies": response != 0,
        "herm_gap_bracket": bracket(herm_gap),
        "herm_response_bracket": bracket(herm_response),
        "herm_literals_agree": (
            herm_gap == R(*HERM_TWIN_MAX_8)
            and herm_response == R(*HERM_RESPONSE_MAX_8)),
        "twin_literal_agrees": twin_gap == R(*TAIL_MAX[8]),
        "response_literal_agrees": response == R(*RESPONSE_MAX_8),
        "translation_broken": t_count > 0,
        "translation_count": t_count,
        "translation_witness": t_witness,
        "reflection_counts": tuple(c for c, _ in reflections),
        "reflections_broken": all(c > 0 for c, _ in reflections),
        "reflection_witness": reflections[0][1],
        "realification": dm_det(realified) == norm2(detspot),
        "dial_points": len(points),
        "dial_total": len(DIAL_POINTS),
        "dial_deep": deep,
        "pd_nonzero_mass": all(p["pd_arms"] == len(MENU) for p in nonzero),
        "pd_pivot_counts": tuple(sorted({v for p in nonzero
                                         for v in p["pivots"]})),
        "zero_mass_sampled": len(zero) == 1,
        "zero_mass_pd_arms": zero[0]["pd_arms"] if zero else None,
        "zero_mass_herm_zero": zero[0]["herm_is_zero"] if zero else None,
        "zero_mass_dets_nonzero": zero[0]["dets_nonzero"] if zero else None,
        "zero_mass_first_pivot": zero[0]["first_bad"] if zero else None,
        "nonzero_mass_expected": len(DIAL_POINTS) - 1,
        "points": tuple(points),
    }


def measure_levels() -> dict:
    """C2: t_r = 2..5 give four pairwise-distinct exact laws."""
    const = Fixture(4, pattern=constant_pattern(4), tag="level")
    laws = {}
    for level in LEVELS:
        laws[level] = readout_laws(menu_states(const, level, 0))
    deltas = {}
    for level in LEVELS[1:]:
        gap, _ = law_gap(laws[level], laws[LEVELS[0]], "sq")
        deltas[level] = gap
    vectors = {tuple(laws[level]["sq"]["law"]) for level in LEVELS}
    return {
        "levels": LEVELS,
        "distinct": len(vectors),
        "pairwise_distinct": len(vectors) == len(LEVELS),
        "deltas": deltas,
        "brackets": {level: bracket(deltas[level]) for level in deltas},
        "literals_agree": all(
            deltas[level] == R(*LEVEL_DELTA_MAX[level])
            for level in deltas),
        "single_site_law": len(vectors) == 1,
    }


def measure_tail(family: dict, deep: bool) -> dict:
    """The twin gap at increasing width: the geometric decay, exact.

    The L_x = 8 width is the SAME computation gate F reads, so it is REUSED from
    the family measurement rather than rebuilt; the wider widths are new.
    """
    widths = DEEP_TAIL_WIDTHS if deep else TAIL_WIDTHS
    gaps = {}
    for lx in widths:
        if lx == 8:
            gap, _ = law_gap(family["cells"]["twin0"], family["cells"]["twin4"],
                             "sq")
            gaps[lx] = gap
            continue
        pattern = twin_pattern(lx)
        fixture = Fixture(lx, pattern=pattern, tag=f"tail{lx}")
        left = readout_laws(menu_states(fixture, RECORD_LEVEL, 0))
        right = readout_laws(menu_states(fixture, RECORD_LEVEL, lx // 2))
        gap, _ = law_gap(left, right, "sq")
        gaps[lx] = gap
    ordered = sorted(gaps)
    ratios = {ordered[i + 1]: sp.cancel(gaps[ordered[i + 1]] / gaps[ordered[i]])
              for i in range(len(ordered) - 1)}
    certificates = {lx: pattern_certificate(twin_pattern(lx)) for lx in widths}
    return {
        "widths": tuple(widths),
        "deep": deep,
        "gaps": gaps,
        "brackets": {lx: bracket(gaps[lx]) for lx in widths},
        "literals_agree": all(gaps[lx] == R(*TAIL_MAX[lx]) for lx in widths),
        "strictly_decreasing": all(gaps[ordered[i + 1]] < gaps[ordered[i]]
                                   for i in range(len(ordered) - 1)),
        "ratios": ratios,
        "ratios_below_one": all(v < 1 for v in ratios.values()),
        "all_nonzero": all(v != 0 for v in gaps.values()),
        "certificates": certificates,
        "symmetries_broken": all(
            not c["translations"] and not c["reflections"]
            and c["same_blanket"] and len(c["mismatches"]) == 1
            for c in certificates.values()),
        "asymptotic_supported_not_proven": True,
        "widths_are_not_a_limit": True,
    }


