# ---------------------------------------------------------------------------
# claims: the only thing a mutation is allowed to touch
# ---------------------------------------------------------------------------
def build_claims(mutation: str) -> dict:
    claims: dict = {
        "main_head": CURRENT_MAIN,
        "parent_pin": "resolved",
        "hygiene_sites_absent": True,
        "only_support_has_force": False,
        "censuses_closed": True,
        "pigeonhole_kills_12x4": False,
        "quotient_generated": False,
        "modulus_squared_forced": False,
        "surrogate_chart_sensitive": False,
        "blanket_local_exact": False,
        "pd_at_zero_mass": False,
        "single_site_law": False,
        "tail_decreases": True,
        "required_scope_keys": SCOPE_KEYS,
    }
    if mutation == "stale_main_authority":
        claims["main_head"] = STALE_MAIN
    elif mutation == "stale_parent_authority":
        claims["parent_pin"] = "stale"
    elif mutation == "claim_hygiene_sites_present":
        # THE PARENT'S OWN CONTENT DENIED: the four repaired call sites asserted
        # still present, which reading the three repaired files forbids.
        claims["hygiene_sites_absent"] = False
    elif mutation == "claim_only_support_has_force":
        # THE BROAD SLOGAN RE-ASSERTED: "only support has axiom force", which the
        # review REJECTED -- the odds are law content, they merely do not
        # constrain which record configurations are realizable.
        claims["only_support_has_force"] = True
    elif mutation == "claim_censuses_open":
        # BOTH CLOSURES DENIED: finite-size exact Form B asserted still open,
        # which 0 of 16 at 8x4 and 0 of 256 at 12x4 with no LCM dividing N
        # forbid.
        claims["censuses_closed"] = False
    elif mutation == "claim_pigeonhole_kills_12x4":
        # THE WIRING ERROR RE-ASSERTED: the pigeonhole asserted to close 12x4,
        # which N = 4 = |A| forbids -- it obstructs only when N < |A|.
        claims["pigeonhole_kills_12x4"] = True
    elif mutation == "claim_quotient_generated":
        # THE REFUTED ATTRIBUTION RE-ASSERTED: the (1,2) hop asserted generated
        # by the quotient, which the exact cover witness Q_cov = 33/128 before
        # any quotient forbids.
        claims["quotient_generated"] = True
    elif mutation == "claim_modulus_squared_forced":
        # THE REFUTED C1 RE-ASSERTED: modulus-squared asserted FORCED by the
        # integral, which the identical pass/fail pattern of four readouts on the
        # four advertised obligations forbids.
        claims["modulus_squared_forced"] = True
    elif mutation == "claim_surrogate_chart_sensitive":
        # THE FINGERPRINT DENIED: the Hermitian surrogate asserted chart-
        # sensitive, which its measured P_0 = P_1 = P_2 forbids.
        claims["surrogate_chart_sensitive"] = True
    elif mutation == "claim_blanket_local_exact":
        # OBLIGATION 3 DENIED: the law asserted EXACTLY blanket-determined, which
        # the exactly nonzero twin gap at matched blankets forbids.
        claims["blanket_local_exact"] = True
    elif mutation == "claim_pd_at_zero_mass":
        # THE C5 DOMAIN CORRECTION DENIED: positive-definiteness asserted at
        # m = 0, which herm(Q) = 0 identically with first pivot 0 forbids.
        claims["pd_at_zero_mass"] = True
    elif mutation == "claim_single_site_law":
        # THE REFUTED C2 RE-ASSERTED: one translation-free site law asserted,
        # which four pairwise-distinct exact laws at t_r = 2..5 forbid.
        claims["single_site_law"] = True
    elif mutation == "claim_tail_grows":
        # THE DECAY DENIED: the twin tail asserted not to decrease with width,
        # which the exact strictly decreasing sequence forbids.
        claims["tail_decreases"] = False
    elif mutation == "drop_readout_gap":
        # THE SUCCESSOR QUESTION DROPPED: the note's naming of the missing
        # readout principle removed from the required scope, which gate H
        # forbids -- the full key set is required, not a subset.
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key not in READOUT_KEYS)
    elif mutation == "drop_n5_fence":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key != "n5_verbatim")
    return claims


